DO $$
DECLARE
  rec RECORD;
  cur_status INT;
  cur_viewer INT;
BEGIN
  FOR rec IN SELECT * FROM watch_events ORDER BY event_id LOOP
    SELECT watch_status, viewer_id INTO cur_status, cur_viewer FROM content_items WHERE item_id = rec.item_id;
    IF rec.event_type = 1 AND cur_status = 0 THEN
      UPDATE content_items SET watch_status = 1, viewer_id = rec.viewer_id WHERE item_id = rec.item_id;
    ELSIF rec.event_type = 2 AND cur_status = 1 AND cur_viewer = rec.viewer_id THEN
      UPDATE content_items SET watch_status = 2 WHERE item_id = rec.item_id;
    ELSIF rec.event_type = 3 AND cur_status = 2 AND cur_viewer = rec.viewer_id THEN
      UPDATE content_items SET watch_status = 1 WHERE item_id = rec.item_id;
    ELSIF rec.event_type = 4 AND cur_status = 1 AND cur_viewer = rec.viewer_id THEN
      UPDATE content_items SET completion_pct = LEAST(completion_pct + rec.progress_delta, 100), watch_status = 0, viewer_id = NULL WHERE item_id = rec.item_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM content_items ORDER BY item_id;

