DO $$
DECLARE
   r RECORD;
   current_status INT;
   current_viewer INT;
   current_completion_pct INT;
BEGIN
   FOR r IN SELECT * FROM watch_events ORDER BY event_id LOOP
       SELECT watch_status, viewer_id, completion_pct
       INTO current_status, current_viewer, current_completion_pct
       FROM content_items
       WHERE item_id = r.item_id;

       IF r.event_type = 1 AND current_status = 0 THEN
           UPDATE content_items
           SET watch_status = 1,
               viewer_id = r.viewer_id
           WHERE item_id = r.item_id;

       ELSIF r.event_type = 2 AND current_status = 1 AND current_viewer = r. viewer_id THEN
           UPDATE content_items
           SET watch_status = 2,
               viewer_id = r.viewer_id
           WHERE item_id = r.item_id;

       ELSIF r.event_type = 3 AND current_status = 2 AND current_viewer = r. viewer_id THEN
           UPDATE content_items
           SET watch_status = 1,
               viewer_id = r.viewer_id
           WHERE item_id = r.item_id;

       ELSIF r.event_type = 4 AND current_status = 1 AND current_viewer = r. viewer_id THEN
           UPDATE content_items
           SET watch_status = 0,
               completion_pct = LEAST(completion_pct + r.progress_delta, 100),
               viewer_id = NULL
           WHERE item_id = r.item_id;
        END IF;
   END LOOP;
END $$;

SELECT * FROM content_items;
